// Pre-register all bundled icons in Iconify's local memory registry
for (const [iconId, iconData] of Object.entries(BUNDLED_ICONS)) {
  addIcon(iconId, iconData);
}

/**
 * Resolves an icon name or raw identifier to a local IconifyIcon definition.
 */
export function getBundledIcon(nameOrId?: IconName | string): IconifyIcon | string {
  if (!nameOrId) return "";
  if (nameOrId in ICONS) {
    const iconId = ICONS[nameOrId as IconName];
    return BUNDLED_ICONS[iconId] || iconId;
  }
  return BUNDLED_ICONS[nameOrId] || nameOrId;
}
